gold_shacl:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .

inst:Question_1_Shape a sh:NodeShape ;
    sh:targetClass cmpo:CMPProcess ;
    sh:property [
        sh:path cmpo:hasTimestamp ;
        sh:minCount 1 ;
        sh:datatype xsd:dateTime ;
        sh:message "Every CMP process run must have a valid measurement timestamp (xsd:dateTime)."
    ] ;
    sh:property [
        sh:path cmpo:hasInput ;
        sh:minCount 1 ;
        sh:message "Every CMP process run must specify at least one wafer input via hasInput."
    ] .

positive_cases:
@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

inst:Run_A a cmpo:CMPProcess ;
    cmpo:hasTimestamp "2026-03-31T10:00:00Z"^^xsd:dateTime ;
    cmpo:hasInput inst:Wafer_101 .

@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

inst:Run_B a cmpo:CMPProcess ;
    cmpo:hasTimestamp "2026-03-31T11:30:00Z"^^xsd:dateTime ;
    cmpo:hasInput inst:Wafer_102, inst:Wafer_103 .

negative_cases:
@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .

inst:Run_Bad_NoTimestamp a cmpo:CMPProcess ;
    cmpo:hasInput inst:Wafer_101 .

@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

inst:Run_Bad_NoInput a cmpo:CMPProcess ;
    cmpo:hasTimestamp "2026-03-31T10:00:00Z"^^xsd:dateTime .

gold_shacl:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix cmpo: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo#> .
@prefix inst: <https://vsr.informatik.tu-chemnitz.de/ontologies/cmpo/instance/> .

inst:Question_2_Shape a sh:NodeShape ;
    sh:targetClass cmpo:Pressure ;
    sh:property [
        sh:path cmpo:hasNumericValue ;
        sh:minCount 1 ;
        sh:datatype xsd:float ;
        sh:minInclusive 0.0 ;
        sh:message "Pressure numeric value must be a non-negative float."
    ] ;
    sh:property [
        sh:path cmpo:hasUnit ;
        sh:minCount 1 ;
        sh:hasValue "psi" ;
        sh:message "Pressure values must be measured in 'psi' units."
    ] .

